import unittest

from timesheet.entries import parse_entry, summarize, total_hours


class ParseEntryTest(unittest.TestCase):
    def test_minutes_and_task(self):
        entry = parse_entry("2026-09-18 09:00-10:30 review")
        self.assertEqual(entry["minutes"], 90)
        self.assertEqual(entry["task"], "review")

    def test_date_and_times(self):
        entry = parse_entry("2026-09-18 13:15-14:00 standup")
        self.assertEqual((entry["date"], entry["start"], entry["end"]), ("2026-09-18", "13:15", "14:00"))

    def test_malformed(self):
        with self.assertRaises(ValueError):
            parse_entry("yesterday 9-10 review")


class SummarizeTest(unittest.TestCase):
    def test_groups_by_task(self):
        entries = [
            parse_entry("2026-09-18 09:00-10:30 review"),
            parse_entry("2026-09-18 10:30-11:00 standup"),
            parse_entry("2026-09-18 13:00-14:00 review"),
        ]
        self.assertEqual(summarize(entries), {"review": 2.5, "standup": 0.5})

    def test_empty(self):
        self.assertEqual(summarize([]), {})

    def test_rounding(self):
        entries = [parse_entry("2026-09-18 09:00-09:07 review")]
        self.assertEqual(summarize(entries), {"review": 0.12})


class TotalHoursTest(unittest.TestCase):
    def test_total(self):
        entries = [
            parse_entry("2026-09-18 09:00-10:30 review"),
            parse_entry("2026-09-18 23:30-01:00 review"),
        ]
        self.assertEqual(total_hours(entries), 4.0)

if __name__ == "__main__":
    unittest.main()

